begin;
set search_path=public,extensions;
select plan(16);
insert into auth.users(id,email,raw_user_meta_data) values('18000000-0000-4000-8000-000000000001','gym18@example.invalid','{"display_name":"Gym"}');
set local role authenticated;
set local "request.jwt.claim.sub"='18000000-0000-4000-8000-000000000001';
insert into public.gym_routines(id,user_id,name) values('18000000-0000-4000-8000-000000000002',auth.uid(),'Chest–Tricep–Shoulders');
insert into public.gym_exercises(id,routine_id,user_id,name,sets,reps,rest_seconds,rir) values('18000000-0000-4000-8000-000000000003','18000000-0000-4000-8000-000000000002',auth.uid(),'Bench press',3,'8-12',90,2);
select lives_ok($$select public.reorder_gym_exercises('18000000-0000-4000-8000-000000000002',array['18000000-0000-4000-8000-000000000003'::uuid])$$,'atomic reorder accepts exact exercise set');
select lives_ok($$select public.start_gym_session('18000000-0000-4000-8000-000000000002')$$,'starts draft');
select is(public.start_gym_session('18000000-0000-4000-8000-000000000002'),(select id from public.gym_sessions where status='draft'),'start resumes same draft');
select is((select count(*) from public.gym_sessions),1::bigint,'one draft');
select lives_ok($$select public.save_gym_session((select id from public.gym_sessions), '[{"exercise_id":"18000000-0000-4000-8000-000000000003","weight":40}]',false)$$,'save draft weight');
select is((select weight from public.gym_entries),40.000::numeric,'weight persists');
select throws_ok($$select public.save_gym_session((select id from public.gym_sessions),'[{"exercise_id":"18000000-0000-4000-8000-000000000003","weight":-1}]',true)$$,'23514',null,'negative weight rolls back finish');
select is((select status from public.gym_sessions),'draft','failed finish remains draft');
select lives_ok($$select public.save_gym_session((select id from public.gym_sessions),'[]',true)$$,'finishes session');
select lives_ok($$select public.save_gym_session((select id from public.gym_sessions),'[]',true)$$,'duplicate finish no-op');
select is((select count(*) from public.gym_sessions where status='completed'),1::bigint,'exactly one history session');
update public.gym_exercises set name='Changed',sets=4 where id='18000000-0000-4000-8000-000000000003';
delete from public.gym_exercises where id='18000000-0000-4000-8000-000000000003';
select is((select prescription->>'name' from public.gym_entries),'Bench press','history snapshot survives edit/removal');
select throws_ok($$update public.gym_entries set weight=500$$,'42501',null,'client cannot rewrite history');
set local "request.jwt.claim.sub"='18000000-0000-4000-8000-000000000099';
select is((select count(*) from public.gym_sessions),0::bigint,'other account cannot read sessions');
select throws_ok($$select public.start_gym_session('18000000-0000-4000-8000-000000000002')$$,'P0001','Routine not available.','other account cannot start');
select throws_ok($$insert into public.gym_exercises(routine_id,user_id,name,sets,reps,rest_seconds,rir) values('18000000-0000-4000-8000-000000000002',auth.uid(),'Foreign',3,'10',30,2)$$,'23503',null,'cannot attach own exercise to foreign routine');
select * from finish();
rollback;
